@startuml

class FurnitureLine {
  +name : string
}

class Furniture {
  +reference : string
  +sellingPrice : double
}

class ComponentType {
  +code : int
  +manufacturingPrice : double
  +type : string
}

class Store {
  +address : string
  +faxNumber : string
}

class Order {
  +orderNumber : int
  +date : date
}

class OrderLine {
  +quantity : int
}

FurnitureLine "1" *-- "1..*" Furniture
Furniture "1" -- "*" FurnitureLine : consistsOf
Furniture "*" -- "*" ComponentType
Furniture "*" -- "*" OrderLine
OrderLine "*" -- "1" Furniture
Order "1" -- "1" Store : placedBy
Order "1" -- "1..*" OrderLine

@enduml

